import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"漸","description":"高島易斷 - 漸","frontmatter":{"title":"漸","description":"高島易斷 - 漸"},"headers":[],"relativePath":"classics/takashima/053.md","filePath":"classics/takashima/053.md"}'),i={name:"classics/takashima/053.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><h2 id="漸-1" tabindex="-1">漸 <a class="header-anchor" href="#漸-1" aria-label="Permalink to “漸”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>漸：女歸吉，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《漸》反為《歸妹》，其象同取於女，《歸妹》之少女，以悅而歸，不如《漸》之長女，以順而歸也。以順而歸，則媒妁言之，父母命之，及長而字，則漸而來，得其正也，故曰“女歸吉”。《艮》男《兌》女，其卦曰《鹹》，以男娶女也，故先戒以“利貞”，而後曰“娶女吉”；《漸》以《艮》男《巽》女，以女歸男也，故先曰“女歸吉”，而後告以“利貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山上有木，漸。君子以居賢德善俗。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>山上有木，以木在山，為得其所，猶女子以歸為得所。君子法此象，觀木之由漸而長，非一時所可成，即知俗之由漸而善，非一旦所能化。要必先居德以為表率，使之漸仁摩義，而風俗自善。古稱缺妻之賢，孟光之德，足以化俗，況士君子之躬居賢德者乎？其化民成俗，固有日進而日善者也。全卦皆取《巽》女，而《象》獨稱“君子”，蓋《艮》為賢人，故曰“君子居賢德”。要知君子與淑女，足為配偶，其德同，其化亦同也。“善俗”，王肅本作風俗，“居賢德”，《本義》雲“賢字衍”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：如木在高山，得逢春生髮之象。</p><p>○　問營商：山藏貨財，木能生髮，且《巽》為商，利市三倍，得此卦象，自必能逐漸得利也。</p><p>○　問功名：足膺賢才之選。</p><p>○　問戰徵：防三軍前進，在深山茂林之處，有敵兵埋伏。</p><p>○　問婚姻：必是賢德淑女，是以“君子好逑”。</p><p>○　問家宅：必是德門仁裡，君子居之。</p><p>○　問疾病：是木克土之症，宜安居調養。</p><p>○　問六甲：望前生者男，望後生者女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>鴻，水禽，來往有時，群飛有序。相傳漢土婚禮用雁，取其飛行不亂，失偶不再，有女貞之象。大曰鴻，小曰雁，鴻與雁一也。《彖》曰“女歸”，故六爻皆取喻於鴻。“幹”，水湄，鴻漸幹而得所棲，猶女適人而得所託。但《艮》為少男，故稱“小子”，《巽》為長女，一長一少，年齒相懸，未免於歸愆期，或有不測之變，是為“小於厲”也。《說卦》“成言乎艮”，有言，為有成言也。女子許嫁，惟憑媒妁之言，既有其言，不得以有變而渝，故曰“有言無咎”。初應在上，初與上爻，高下懸殊，即可見夫婦年齒，長幼亦懸殊。女能待年不亂，守禮無失，無所為厲，復有何咎？《彖傳》以“義無咎”釋之，蓋謂義在則然，咎自無焉。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：人微年少，運途初行，雖危無咎。</p><p>○　問戰徵：屯軍江干，防有危厲，幸有諜言來告，得以免咎。</p><p>○　問營商：貨物交易，防有小人從中作難，因約言早成，得以無害。</p><p>○　問功名：鴻運亨通，初雖在下，自有漸進之象。</p><p>○　問婚姻：女長男少，妁言既定，當以待年而嫁，無咎也。</p><p>○　問家宅：此宅臨水，防小人有疾厄，然無大咎。</p><p>○　問疾病：不利小人，大人無咎。</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來請佔事業成否，筮得《漸》之《家人》。</p><p>斷曰：《漸》者，漸而進也，《漸》在初爻，為進步之初基也。“幹”，水涯，亦低下之處。君佔事業，得《漸》初爻，知君此業，必是初次開辦，如秋雁初來，尚在江干飛集，未得遠翔。凡事業初創，未免有小人出而阻擾，務要把定初志，不改成言，是得無咎。然在初爻，其進猶微，必得四年後，行到上爻，則得其應援，必可大獲利益也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>磐者，水中平石，“衎衎”，和樂之貌。“鴻漸於磐”，有水可飲，有蒲魚稻梁可食，為足樂也，猶女子嫁得其夫，合巹而飲，共牢而食，自見“宜室宜家，和樂且耽”。二與五相應，即為配偶，婦人賢德，足以內助，固非虛食夫家之食者也。《彖傳》以“不素飽”釋之，即此意也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：既得安樂，又得醉飽無憂，吉。</p><p>○　問戰徵：兵食充足，軍心歡悅，自有安似磐石之象。</p><p>○　問營商：二爻居《巽》之中，《巽》為商，為利。就爻辭言“幹”進“磐”，有漸進漸高之勢，吉。</p><p>○　問功名：有嘉賓宴樂之象，成名必矣，吉。</p><p>○　問婚姻：二與五相應，即以二五為婚；二五皆吉，可詠百年偕老矣。</p><p>○　問家宅：此宅地基鞏固，一門和樂，吉。</p><p>○　問疾病：飲食過度所致，宜消食安胃，病即日可愈。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十三年，佔某貴顯氣運，筮得《漸》之《巽》。</p><p>斷曰：二爻居《巽》之中，《巽》，順也。爻辭曰“鴻漸於磐”，鴻，大雁也，磐，山石之安者。貴下佔氣運得此爻，知貴下鴻運通順，持躬涉世，皆得安如磐石，無人得而動搖。由“幹”進“磐”，見鴻飛蹤跡，逐步增高，喻貴下卒業東北學校，繼復遊學歐美各邦，學識亦漸步長進。且二爻與五相應，爻以夫婦和諧，即可見君巨之喜樂，至美衣飽食，和樂衎衎，本貴下所素有也，吉何如也！</p><p>明治三十二年，佔北海道廳氣運，筮得《漸》之《巽》。</p><p>斷曰：《漸》者漸進也，由亂而進於治，由衰而進於盛，皆有漸進之象焉。今佔北海道廳氣運，而得《漸》之二爻，爻辭曰“鴻漸於磐”，由“幹”而進於“磐”，是亦漸進而漸高也，知北海道廳治象，當必日進日盛。爻又曰“飲食衎衎”，在北海一帶，為魚臨蜃蛤之鄉，其足供飲食者，出產饒富，民居斯土，獲斯利，家室豐盈，雍雍和樂，自得“飲食衎衎”之喜。爻辭曰“吉”，信可知也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“陸”，高平之地，鴻所集也。九三陽剛為夫，六四陰柔為婦，三又與六正應，六亦曰“陸”。自內往外為徵，三往就外之陸，而遂棄內之陸，故“不復”。上互《離》，《離》為大腹，孕之象；下互《坎》，《坎》為災，為鬼，不育之象。三與四以比鄰私通，壞彝倫之大綱，背漸進之大義，安能得室家和睦，夫婦偕老，生育以延嗣續之庥乎？故曰“夫徵不復，婦孕不育，兇”。且雁呼蘆避繳，巡呼警夜，飛則相隨，止則相保，亦有禦寇之象，故曰“利禦寇”。夫鴻之有雌雄，猶人之有夫婦也，雄飛不返，是離其群矣；胎孕之道，期其長育，孕而不育，是失其道矣。雌雄相守，是所以“禦寇”，是“順相保”也。《彖傳》逐句釋之，有以夫！</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：運途不正，防有外禍。</p><p>○　問戰徵：利於守禦，不利往徵。</p><p>○　問營商：難望獲利，防有盜劫之虞。</p><p>○　問功名：惟從事軍政，可以得名。</p><p>○　問婚姻：防有始亂終離之憾。</p><p>○　問家宅：此宅於生產不利。</p><p>○　問疾病：婦人生產，恐母子不能兩全。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>昔餘在囚之日，有獄吏和田某者，突然謂餘曰：今茲罪案，曷不卜之？先是餘自佔氣運，得《艮》之《漸》，斷辭詳記需三爻；今復一佔，筮得《漸》之《觀》。</p><p>斷曰：“夫徵不復”，謂此案已往，不復追究矣。“婦孕”者，謂禍胎也，“不育”者，謂此案不致再生枝節矣。“禦寇”者，謂審獄之官也；“順相保”者，謂必能保護我身也。然所謂相保者，當必在和田氏矣。後一二旬，前奉行退職，清水某襲其後，和田氏為奉行次席，於是二氏相謀，以五十月徒期，減為二十月，餘乃得以出罪。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四居《巽》之始，《巽》為木。鴻水鳥，本不棲木，“桷”者，枝柯之大而平者也，於木之中，而得方平之桷，則亦可以容足矣。“或”者幸得之辭，此以鴻之失所，喻婦之失所也。四夫在三，三“徵不復”，四婦失其所矣，或得其桷而集之，亦無咎焉。巽順自守，不失婦道之正，雖無夫可也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：運失其正，但以順自處，隨遇得安，亦可無咎。</p><p>○　問營商：聊有所得，差足免咎。</p><p>○　問戰徵：得其倚角，敵勢已衰。</p><p>○　問功名：從事角逐，所得亦微。</p><p>○　問疾病：病在肝木太盛，宜順氣調養。</p><p>○　問家宅：此宅多寡居之婦，有遇人不淑之感。</p><p>○　問行人：在外失年，聊以將順容身，一時不歸。</p><p>○　問六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>舊大垣藩主華族戶田氏，奉侍萱堂，借餘神奈川別墅，閒居養病者數月，醫士戶冢文海氏間日自東京來診。一日戶冢氏謂餘曰：診視戶田太君之疾，四五日前，頗為可慮，近少輕快，惟老衰難期速效。餘曰：頃日代為問卜筮得《漸》之《遁》，今玩爻辭，知太君近病無妨，恐明後年命限有阻。</p><p>戶冢氏俯首不語。有松野家老出而問曰：我太君之命，其終於明後年乎？餘曰：請勿與外人道也！後三年，太君果仙逝，會葬之日，戶冢氏追述前言，感嘆《易》理之前知。蓋《漸》為長女，卦為歸魂，自四至上，三爻為三年，由是推之，死期可預決也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>《爾雅》，“大阜曰陵”；又八陵，北陵、西俞、雁門是也。此陵當是北陵，雁之家也。《月令》，“季秋鴻雁來賓”，鴻之南來為賓，北陵則為家，孕育則在家也。五與二正應，為夫婦，故以“鴻漸於陵”，喻夫婦之居家也。三至五互《離》，《離》為大腹，三動則《離》壞，故“不孕”；自二至五歷三爻，象“三歲”。《艮》少男，《巽》長女，女及笄，而男猶未冠，是以不能生育，迨及時而陰陽和合，自然得孕矣。男少女長，似女偏勝，然二五正應，內外得當，夫倡婦隨，故曰“終莫之勝”。時至而孕，各得所願，吉可知也。又云：此卦三五皆言婦，九五以二為婦，正也，九三以四為婦，非正也。故三四相比為夫婦，雖孕而不敢育。女之歸不以漸也，故兇；二五以相應為夫婦，不孕而得所願，女之歸以漸也，故吉。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：運途中正，三年後，無往不利，吉。</p><p>○　問戰徵：屯軍大阜，三年後，所向無敵，吉。</p><p>○　問功名：三年後必成。</p><p>○　問營商：目下難望獲利，至上爻自可獨佔厚利，蓋在三歲後也。</p><p>○　問婚姻：得子稍遲，吉。</p><p>○　問家宅：宅在大阜之間，吉。</p><p>○　問六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>某商人來請佔氣運，筮得《漸》之《艮》。</p><p>斷曰：五居外卦之中，進步已高，得漸於大阜之上，無可再進也。足下佔氣運而得此爻，知足下營商多載，雖事業漸進漸高，而不得一時獲利，如鴻鳥雌雄相隨，而一大一小，未能即時生育也。鴻待三年後可孕，知商業亦必待三年後，可獲大利也。“終莫之勝”者，謂非他人所能及也。爻辭曰“吉”，吉可知也。《象》曰“得所願”，知足下平生之志願，可遂矣。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上與三皆處卦極，故並稱“陸”。《漸》卦六爻，皆取象於鴻，以喻夫婦，即本《彖》辭“女歸”之旨。三之《漸》“陸”，夫道不正，致婦失所，不如鴻之雌雄相守；上則猶是陸也，猶是漸也，而以禮相接，人鹹稱美，不特表閨閫之令範，且足樹邦國之合儀矣。一羽本輕，而先王制禮，納采問名，皆取以為用，非以其有偶而不亂乎？夫婦之道，亦如是焉，故曰“其羽可用為儀”。“女歸”之“吉”，其以此乎？</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：氣運正盛，可出而用也，吉。</p><p>○　問戰徵：從平陸進軍，威儀顯赫，攻無不克</p><p>○　問營商：貨美價高，定可獲利。</p><p>○　問功名：出而用世，可以儀表天下。</p><p>○　問婚姻：吉。</p><p>○　問家宅：此宅地位崇高，瞻觀有耀，吉。</p><p>○　問六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治十九年，虎列喇病流行於橫濱，凡橫濱店中，家族皆避疫於神奈川別莊，東京之友，皆歸東京，餘攜遠來學者八人，赴箱根木賀。一日有東京門人，判事尾藤某來狀，其旨曰：今度拜命，赴越後高田裁判所長，臨發自筮，爻象不吉，請為再佔氣運如何？筮得《漸》之《蹇》。</p><p>斷曰：全卦以漸進為義，爻至上六，漸進之義已終，進無可進，是暖回冰解，鴻鳥北還之時。今佔尾藤氏氣運，得此上爻，知為新授北國高田判事之任。爻辭所云“鴻漸於陸”，辭意適合，本是吉象，但此爻《易》三百八十四爻中，為歸魂八爻之一，佔者當此，生命有阻。因嘆曰：氏為餘門人中之翹楚，他日繼餘《易》學者，在此人也，大為可惜！一時從者聞此斷詞，皆謂共在一堂，何得以一筮之下，遽斷必死？後尾藤赴任高田，未幾果歿。</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
